// Loaded from the business WhatsApp number saved in Admin.
let siteContent = null;
let KASIGO_WHATSAPP = '';
let slideTimer = null;
let cartSyncTimer = null;
const modal = document.querySelector('#modal');
const form = document.querySelector('#delivery-form');
const tracking = document.querySelector('#tracking-panel');
const estimate = document.querySelector('#estimate');
let selectedShop = '';

function normalizeBusinessWhatsApp(value) {
  let digits = String(value || '').replace(/\D/g, '');
  if (digits.startsWith('00')) digits = digits.slice(2);
  if (digits.length === 10 && digits.startsWith('0')) digits = `27${digits.slice(1)}`;
  return digits;
}

function whatsapp(message) {
  trackActivity('whatsapp_intent',location.pathname);
  if (!KASIGO_WHATSAPP) {
    document.querySelector('#modal-kicker').textContent = 'WHATSAPP CHECKOUT SETUP';
    document.querySelector('#modal-title').innerHTML = 'WhatsApp number<br><em>not added yet.</em>';
    document.querySelector('#modal-desc').textContent = 'Add the KasiGo business WhatsApp number in Admin → Homepage settings before accepting orders.';
    return;
  }
  window.open(`https://wa.me/${KASIGO_WHATSAPP}?text=${encodeURIComponent(message)}`, '_blank', 'noopener,noreferrer');
}
function openModal(mode) {
  modal.classList.add('open'); modal.setAttribute('aria-hidden', 'false'); document.body.style.overflow = 'hidden';
  form.style.display = 'block'; tracking.classList.remove('active'); selectedShop = '';
  document.querySelector('#modal-kicker').textContent = 'LET\'S GET IT MOVING';
  document.querySelector('#modal-title').innerHTML = 'Send something<br><em>somewhere.</em>';
  document.querySelector('#modal-desc').textContent = 'Share a few details and we\'ll pick things up on WhatsApp.';
  if (mode === 'track') {
    form.style.display = 'none'; tracking.classList.add('active');
    document.querySelector('#modal-kicker').textContent = 'A LITTLE UPDATE GOES A LONG WAY';
    document.querySelector('#modal-title').innerHTML = "Where's your<br><em>good stuff?</em>";
    document.querySelector('#modal-desc').textContent = 'Enter the delivery reference from your WhatsApp conversation.';
  } else if (mode === 'whatsapp') {
    document.querySelector('#modal-kicker').textContent = 'WE\'RE JUST A MESSAGE AWAY';
    document.querySelector('#modal-title').innerHTML = 'Let\'s have a<br><em>quick chat.</em>';
    document.querySelector('#modal-desc').textContent = 'We can help with an order, a delivery, or getting your business on KasiGo.';
    whatsapp('Hi KasiGo! I would like to ask about your delivery services.');
  } else if (mode === 'partner') {
    document.querySelector('#modal-kicker').textContent = 'GOOD PEOPLE, WORKING TOGETHER';
    document.querySelector('#modal-title').innerHTML = 'Let\'s get your<br><em>business moving.</em>';
    document.querySelector('#modal-desc').textContent = 'Tell us a little about your shop and we\'ll be in touch.';
    whatsapp('Hi KasiGo! I am interested in becoming a business partner.');
  }
  if (mode === 'parcel') document.querySelector('[name="pickup"]').focus({ preventScroll: true });
}
function closeModal() { modal.classList.remove('open'); modal.setAttribute('aria-hidden', 'true'); document.body.style.overflow = ''; }
document.querySelectorAll('[data-open]').forEach(button => button.addEventListener('click', () => button.dataset.open==='parcel' ? showChannelChoice('/send-parcel','Send a parcel') : openModal(button.dataset.open)));
document.querySelectorAll('.shop-order').forEach(button => button.addEventListener('click', () => {
  selectedShop = button.dataset.shop;
  document.querySelector('[name="parcel"]').value = 'Something from a local shop';
  openModal('parcel');
  selectedShop = button.dataset.shop;
}));
document.querySelector('.modal-close').addEventListener('click', closeModal);
modal.addEventListener('click', event => { if (event.target === modal) closeModal(); });
document.addEventListener('keydown', event => { if (event.key === 'Escape') closeModal(); });
document.querySelector('.menu-toggle').addEventListener('click', () => document.querySelector('.nav-links').classList.toggle('active'));
document.querySelectorAll('.nav-links a').forEach(link => link.addEventListener('click', () => document.querySelector('.nav-links').classList.remove('active')));

const cityRates = { johannesburg: 45, pretoria: 55, cape: 65, durban: 60, bloemfontein: 75, gqeberha: 80, polokwane: 75, mbombela: 75, kimberley: 85, eastlondon: 80 };
function cityGroup(value) {
  const v = value.toLowerCase().replace(/\s+/g, '');
  if (/cape|stellenbosch|paarl|gordon|bellville|khayelitsha/.test(v)) return 'cape';
  if (/durban|umhlanga|pinetown|pietermaritzburg|ballito/.test(v)) return 'durban';
  if (/pretoria|centurion|hatfield|soshanguve/.test(v)) return 'pretoria';
  if (/gqeberha|portelizabeth|kariega/.test(v)) return 'gqeberha';
  if (/bloemfontein/.test(v)) return 'bloemfontein';
  if (/polokwane/.test(v)) return 'polokwane';
  if (/mbombela|nelspruit/.test(v)) return 'mbombela';
  if (/kimberley/.test(v)) return 'kimberley';
  if (/eastlondon/.test(v)) return 'eastlondon';
  if (/johannesburg|joburg|sandton|soweto|melville|alexandra|randburg|rosebank|orlando|gardens/.test(v)) return 'johannesburg';
  return null;
}
function updateEstimate() {
  const pickup = document.querySelector('[name="pickup"]').value;
  const dropoff = document.querySelector('[name="dropoff"]').value;
  if (!pickup || !dropoff) { estimate.querySelector('b').textContent = 'Add both locations to see an estimate'; return; }
  const a = cityGroup(pickup), b = cityGroup(dropoff);
  if (!a || !b) { estimate.querySelector('b').textContent = 'We’ll confirm your route on WhatsApp'; return; }
  let fee = a === b ? 45 : Math.max(cityRates[a], cityRates[b]) + (a === 'johannesburg' || b === 'johannesburg' ? 50 : 75);
  if (document.querySelector('[name="speed"]').value === 'Priority') fee += 35;
  estimate.querySelector('b').textContent = `From R${fee} · ${a === b ? 'local delivery' : 'intercity estimate'}`;
}
form.querySelectorAll('input,select').forEach(input => input.addEventListener('input', updateEstimate));
form.addEventListener('submit', event => {
  event.preventDefault();
  const data = new FormData(form);
  const message = `Hi KasiGo! I'd like to arrange a delivery.${selectedShop ? `\nShop: ${selectedShop}` : ''}\nPickup: ${data.get('pickup')}\nDrop-off: ${data.get('dropoff')}\nItem: ${data.get('parcel')}\nTiming: ${data.get('speed')}\nPlease confirm the final price and next steps.`;
  whatsapp(message);
});
document.querySelector('#track-code').addEventListener('input', event => {
  const code = event.target.value.trim();
  document.querySelector('#track-result').innerHTML = code ? `Reference <strong>${code.replace(/[<>&"']/g, '')}</strong> is ready to look up. Send it to our team on WhatsApp and we'll share the latest update.` : 'Enter your reference and we\'ll help you find your delivery.';
});
document.querySelector('#track-whatsapp').addEventListener('click', () => {
  const code = document.querySelector('#track-code').value.trim();
  whatsapp(`Hi KasiGo! Could you please share an update on delivery ${code || '[my delivery reference]'}?`);
});
