function esc(value) { return String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
function routeForm(type) {
  if (type === 'moving') return `<div class="form-row"><label>Moving from<input name="pickup" required placeholder="Current address and city"></label><label>Moving to<input name="dropoff" required placeholder="New address and city"></label></div><div class="form-row"><label>Your name<input name="sender" required placeholder="Name"></label><label>WhatsApp cellphone<input name="phone" required placeholder="Number with country code"></label></div><div class="form-row"><label>What are you moving?<select name="moveType"><option>Home furniture and household items</option><option>Office relocation and equipment</option><option>Large parcel or bulky item</option><option>Furniture delivery</option><option>Other</option></select></label><label>Vehicle preference<select name="vehicle"><option>Recommend a vehicle for me</option><option>Bakkie</option><option>Truck</option></select></label></div><label>Preferred moving date<input name="date" type="date"></label><label>What needs to be moved?<textarea name="description" required rows="4" placeholder="Furniture, office staff/equipment, number of rooms, or large parcels…"></textarea></label>`;
  if (type === 'buy') return `<label>Your name<input name="name" required placeholder="Name"></label><label>WhatsApp number<input name="phone" required placeholder="Your cellphone number"></label><label>Shop or store<input name="shop" required placeholder="e.g. Checkers, Sandton City"></label><label>Shopping list<textarea name="list" required rows="4" placeholder="2 kg chicken, bread, milk and Coke"></textarea></label><div class="form-row"><label>Deliver to<input name="dropoff" required placeholder="Area or address"></label><label>When?<select name="speed"><option>Standard</option><option>Priority</option><option>Schedule for later</option></select></label></div>`;
  if (type === 'parcel' || type === 'collect' || type === 'business') return `<div class="form-row"><label>${type==='collect'?'Collect from':'Pickup'}<input name="pickup" required placeholder="Address, area and city"></label><label>${type==='collect'?'Bring to':'Deliver to'}<input name="dropoff" required placeholder="Address, area and city"></label></div><div class="form-row"><label>${type==='business'?'Business / contact':'Sender name'}<input name="sender" required placeholder="Name"></label><label>Contact cellphone<input name="phone" required placeholder="Number with area code"></label></div><div class="form-row"><label>${type==='collect'?'Recipient name':'Recipient name'}<input name="recipient" required placeholder="Name receiving parcel"></label><label>Recipient cellphone<input name="recipientPhone" required placeholder="Recipient number"></label></div><div class="form-row"><label>Parcel size<select name="size"><option>Documents</option><option>Small</option><option>Medium</option><option>Large</option><option>Other</option></select></label><label>Approx. weight<input name="weight" placeholder="e.g. 2 kg"></label></div><label>What are we moving?<input name="description" required placeholder="Clothing, documents, store order…"></label><label>Delivery urgency<select name="speed"><option>Standard</option><option>Express</option><option>Schedule for later</option></select></label>`;
  return '';
}
function renderCategory(slug) {
  const item = categoryData[slug]; if (!item) return false;
  const storeTiles = (item.links || []).map(key => { const s=catalog[key]; return `<a class="route-store-card" href="/stores/${key}"><span class="route-store-emoji">${s.emoji}</span><span class="shop-tag">${s.type.toUpperCase()}</span><h3>${s.name}</h3><small>${s.place}</small><p>${s.intro}</p><b>View menu & order <i>↗</i></b></a>`; }).join('');
  document.title = `${slug === 'buy-for-me' ? 'Buy For Me' : slug.split('-').map(x=>x[0].toUpperCase()+x.slice(1)).join(' ')} | KasiGo`;
  document.querySelector('main').innerHTML = `<section class="route-hero shell"><a class="back-link" href="/#categories">← All services</a><div class="route-hero-grid"><div><div class="eyebrow">${item.eyebrow}</div><h1>${item.title}</h1><p>${item.description}</p>${item.kind!=='stores'?'<a class="button button-dark" href="#request">Start a request <span>↓</span></a>':''}</div><div class="route-illustration"><span>${item.icon}</span><i>↗</i><small>KASIGO · SOUTH AFRICA</small></div></div><div class="route-breadcrumb">HOME <span>›</span> SERVICES <span>›</span> ${slug.replaceAll('-',' ').toUpperCase()}</div></section>${item.kind==='stores'?`<section class="route-list shell"><div class="eyebrow">LOCAL PARTNERS</div><h2>Good things from<br><em>good people.</em></h2><div class="route-store-grid">${storeTiles}</div><p class="demo-note">These are sample partners for the website preview. Store availability and menus need to be confirmed before launch.</p></section>`:`<section class="request-section" id="request"><div class="shell request-layout"><div><div class="eyebrow">A FEW DETAILS, THEN WE’LL TAKE IT FROM HERE</div><h2>${item.kind==='buy'?'Your shopping<br><em>request.</em>':item.kind==='business'?'Create a delivery<br><em>for a customer.</em>':item.kind==='collect'?'Arrange a<br><em>collection.</em>':'Delivery details<br><em>and parcel.</em>'}</h2><p>We’ll confirm route availability, the final fee and timing with you on WhatsApp before anything is booked.</p><div class="guide-prices"><span>GUIDE PRICES</span><b>Small parcel from R30</b><b>Medium from R45 · Large from R65</b><small>Route, weight and urgency affect final pricing.</small></div></div><form class="route-form" id="route-form">${routeForm(item.kind)}<button class="button button-dark submit-button">Continue on WhatsApp <span>↗</span></button><small>Submitting opens WhatsApp with your details for confirmation.</small></form></div></section>`}`;
  document.querySelectorAll('.back-link').forEach(a=>a.href='/#categories');
  const routeOrder = document.querySelector('#route-form');
  if (routeOrder) routeOrder.addEventListener('submit', e=>{e.preventDefault();const d=new FormData(routeOrder);const lines=[`Hi KasiGo! I would like to arrange ${slug.replaceAll('-',' ')}.`,...Array.from(d.entries()).map(([k,v])=>`${k}: ${v}`)];whatsapp(lines.join('\n'));});
  return true;
}
