  document.querySelector('main').innerHTML=`<section class="store-hero shell"><a class="back-link" href="/food">← Browse services</a><div class="store-banner"><div class="store-banner-emoji">${s.emoji}</div><div><div class="eyebrow">${s.type.toUpperCase()} · ${s.place.toUpperCase()}</div><h1>${s.name}</h1><p>${s.intro}</p><span class="store-rating">★ 4.9 &nbsp; · &nbsp; Local partner</span></div></div><div class="store-nav"><span>MENU</span><span>DELIVERY AVAILABLE IN SELECTED AREAS</span><a href="/#market">All local shops ↗</a></div></section><section class="store-menu shell"><div><div class="eyebrow">MADE FRESH, JUST FOR YOU</div><h2>A few local<br><em>favourites.</em></h2><p class="demo-note">Sample menu for preview. The store confirms availability and final order details on WhatsApp.</p></div><div class="product-list">${s.items.map(([name,price],i)=>`<article class="product-row"><span class="product-thumb">${['✳','❋','◉','✿'][i]}</span><div><b>${name}</b><small>${s.type}</small></div><strong>R${price}</strong><button class="add-product" data-name="${esc(name)}" data-price="${price}">+</button></article>`).join('')}<div class="cart-box"><div><b>Your order</b><span id="cart-total">0 items · R0</span></div><button class="button button-dark" id="checkout-store">Continue on WhatsApp <span>↗</span></button></div></div></section>`;
  const cart=[];document.querySelectorAll('.add-product').forEach(btn=>btn.addEventListener('click',()=>{cart.push({name:btn.dataset.name,price:Number(btn.dataset.price)});btn.textContent='✓';document.querySelector('#cart-total').textContent=`${cart.length} item${cart.length===1?'':'s'} · R${cart.reduce((n,x)=>n+x.price,0)}`;}));
  document.querySelector('#checkout-store').addEventListener('click',()=>{if(!cart.length){document.querySelector('#cart-total').textContent='Add an item to start your order';return;}const total=cart.reduce((n,x)=>n+x.price,0);whatsapp(`Hi KasiGo! I'd like to order from ${s.name}.\n${cart.map(x=>`• ${x.name} — R${x.price}`).join('\n')}\nItems total: R${total}\nPlease confirm availability, delivery fee and next steps.`);});
  return true;
