let adminDraft = null;
const categoryText = slug => slug.replaceAll('-', ' ').replace(/\b\w/g, c => c.toUpperCase());
function renderHomeContent() {
  if (!document.querySelector('#categories')) return;
  const cats = siteContent.categories.filter(c => c.active);
  document.querySelector('#categories .category-grid').innerHTML = cats.map(c => `<a href="/${esc(c.slug)}" class="category-tile"><span class="cat-emoji">${esc(c.icon || '✳')}</span><span><b>${esc(c.name)}</b><small>${esc(c.description || '')}</small></span><i>↗</i></a>`).join('');
  document.querySelectorAll('.category-tile').forEach(link=>link.onclick=e=>{e.preventDefault();showChannelChoice(link.getAttribute('href'),link.querySelector('b').textContent);});
  const featured = siteContent.stores.slice(0, 3);
  const shops = document.querySelector('#shops');
  if (shops) { shops.innerHTML = featured.map(s => `<a href="/stores/${esc(s.slug)}" class="shop-card"><div class="shop-photo photo-coffee">${s.logo?`<img class="shop-logo" src="${s.logo}" alt="${esc(s.name)} logo">`:`<span class="photo-emoji">${esc(s.emoji || '🏪')}</span>`}<span class="shop-tag">${esc(s.type || 'LOCAL PARTNER').toUpperCase()}</span></div><div class="shop-meta"><div><h3>${esc(s.name)}</h3><span>${esc(s.place || '')}</span></div><b>4.9 <i>★</i></b></div><p>${esc(s.intro || '')}</p><span class="shop-order">${s.available ? 'Open store' : 'Currently unavailable'} <span>↗</span></span></a>`).join('');
    shops.querySelectorAll('a').forEach(link=>link.onclick=e=>{e.preventDefault();const store=featured.find(x=>link.href.endsWith(x.slug));showChannelChoice(`/stores/${store.slug}`,store.name,'store');});
  }
  const categoryVideo=document.querySelector('#category-background-video');
  if(siteContent.background?.startsWith('data:video/')){categoryVideo.src=siteContent.background;categoryVideo.hidden=false;document.querySelector('#categories').classList.add('has-background-media');categoryVideo.play().catch(()=>{});}
  else {categoryVideo.hidden=true;categoryVideo.removeAttribute('src');document.querySelector('#categories').classList.remove('has-background-media');document.querySelector('#categories').style.backgroundImage=siteContent.background?`linear-gradient(#F5F7FBcc,#F5F7FBdd),url("${siteContent.background}")`:'';}
  document.querySelector('#hero-subheadline').textContent = siteContent.settings.subheadline || '';
  document.querySelector('#hero-eyebrow-copy').textContent = siteContent.settings.headline || 'YOUR CITY. YOUR PEOPLE. YOUR DELIVERY.';
  const brandName=siteContent.settings.brand||'KasiGo';
  document.title=`${brandName} — Good things are on the way`;
  document.querySelectorAll('.nav .brand > span:last-child,.footer-brand > span:last-child').forEach(el=>el.textContent=brandName);
  document.querySelectorAll('.site-brand-logo').forEach(img=>{const mark=img.parentElement.querySelector('.brand-mark');if(siteContent.settings.logo){img.src=siteContent.settings.logo;img.hidden=false;if(mark)mark.hidden=true;}else{img.hidden=true;if(mark)mark.hidden=false;}});
  document.querySelector('.footer-main>div:first-child p').textContent=siteContent.settings.about||'';
  let contact=document.querySelector('#footer-contact');if(!contact){contact=document.createElement('div');contact.id='footer-contact';contact.className='footer-col';document.querySelector('.footer-main').insertBefore(contact,document.querySelector('.footer-note'));}
  contact.innerHTML=`<b>CONTACT ${esc(brandName.toUpperCase())}</b>${siteContent.settings.phone?`<a href="tel:${esc(siteContent.settings.phone)}">${esc(siteContent.settings.phone)}</a>`:''}${siteContent.settings.email?`<a href="mailto:${esc(siteContent.settings.email)}">${esc(siteContent.settings.email)}</a>`:''}${siteContent.settings.address?`<span>${esc(siteContent.settings.address)}</span>`:''}${KASIGO_WHATSAPP?`<a href="https://wa.me/${esc(KASIGO_WHATSAPP)}" target="_blank" rel="noreferrer">WhatsApp us ↗</a>`:'<span>WhatsApp contact coming soon</span>'}`;
  if (slideTimer) clearInterval(slideTimer);
  let activeSlide = 0;
  const showSlide = index => {
    activeSlide = index;
    const slide = siteContent.slides[index]; const hero = document.querySelector('#hero');
    const heroVideo=document.querySelector('#hero-video');
    if(slide.image?.startsWith('data:video/')){hero.classList.add('has-slide-video');hero.style.backgroundImage='none';heroVideo.src=slide.image;heroVideo.hidden=false;heroVideo.play().catch(()=>{});}
    else {hero.classList.remove('has-slide-video');heroVideo.hidden=true;heroVideo.removeAttribute('src');hero.style.backgroundImage=slide.image?`linear-gradient(90deg,#F5F7FBf2 0%,#F5F7FBdd 43%,#F5F7FB28 100%),url("${slide.image}")`:'linear-gradient(120deg,#F5F7FB 5%,#DCE9FF 100%)';}
    document.querySelector('#hero-headline').innerHTML = esc(slide.title).replace(/\n/g,'<br>');
    const action = document.querySelector('#hero-action'); action.innerHTML = `${esc(slide.action)} <span>↗</span>`; action.href = slide.href;
    document.querySelector('#slide-count').textContent = `0${index + 1} / 03`;
    document.querySelectorAll('.slide-dot').forEach((dot,i)=>dot.classList.toggle('active',i===index));
  };
  document.querySelectorAll('.slide-dot').forEach((dot,index)=>{dot.onclick=()=>{showSlide(index);clearInterval(slideTimer);slideTimer=setInterval(()=>showSlide((activeSlide+1)%3),3000);};});
  document.querySelectorAll('.nav-links a[href="/moving-relocation"]').forEach(link=>link.onclick=e=>{e.preventDefault();showChannelChoice(link.getAttribute('href'),link.textContent.trim());});
  showSlide(0); slideTimer=setInterval(()=>showSlide((activeSlide+1)%3),3000);
}
function contentCategory(slug) {
  const stored = siteContent.categories.find(c => c.slug === slug);
  const preset = categoryData[slug] || {};
  if (!stored && !preset) return null;
  return { ...preset, ...(stored || {}), kind: preset.kind || 'stores', title: preset.title || `${esc(stored?.name || categoryText(slug))}<br><em>with KasiGo.</em>`, eyebrow: preset.eyebrow || 'YOUR NEXT DELIVERY STARTS HERE', links: siteContent.stores.filter(s=>s.category===slug).map(s=>s.slug) };
}
