 const categoryRows=()=>adminDraft.categories.map((c,i)=>`<div class="admin-row category-admin-row" data-category-row="${i}"><label>Category name<input data-cat-field="name" value="${esc(c.name)}"></label><label>URL slug<input data-cat-field="slug" value="${esc(c.slug)}"></label><label>Description<input data-cat-field="description" value="${esc(c.description)}"></label><label>Icon<input data-cat-field="icon" value="${esc(c.icon)}"></label><label class="toggle-label"><input type="checkbox" data-cat-field="active" ${c.active?'checked':''}> Visible on website</label><button class="button button-outline remove-category" data-index="${i}">Remove category</button></div>`).join('');
 const storeCards=()=>adminDraft.stores.length?adminDraft.stores.map((s,i)=>`<article class="admin-store" data-store-row="${i}"><div class="admin-store-head"><div><b>${esc(s.name)}</b><small>${esc(s.slug)}</small></div><label class="toggle-label"><input type="checkbox" data-store-field="available" ${s.available?'checked':''}> Available to customers</label><button class="button button-outline remove-store" data-index="${i}">Remove store</button></div><div class="admin-fields"><label>Store name<input data-store-field="name" value="${esc(s.name)}"></label><label>URL slug<input data-store-field="slug" value="${esc(s.slug)}"></label><label>Category<select data-store-field="category">${adminDraft.categories.map(c=>`<option value="${esc(c.slug)}" ${c.slug===s.category?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label>Store type<input data-store-field="type" value="${esc(s.type)}"></label><label>Area / city<input data-store-field="place" value="${esc(s.place)}"></label><label>Store emoji<input data-store-field="emoji" value="${esc(s.emoji)}"></label><label class="wide-field">Description<input data-store-field="intro" value="${esc(s.intro)}"></label></div><div class="admin-products"><b>Menu and products</b>${(s.products||[]).map((p,j)=>`<div class="admin-product-row" data-product-row="${j}"><input data-product-field="name" value="${esc(p.name)}" aria-label="Product name"><span>R</span><input type="number" min="0" step="0.01" data-product-field="price" value="${Number(p.price)}" aria-label="Product price"><button class="remove-product" data-index="${j}" aria-label="Remove product">×</button></div>`).join('')}<button class="button button-outline add-product-admin" data-index="${i}">+ Add product</button></div></article>`).join(''):'<div class="empty-admin-catalog"><b>No stores or sample products are listed.</b><span>Add your real store details, upload its cover photo and logo, then add the correct products and prices below.</span></div>';
